insert into public.categories (name, slug, description, sort_order, is_active) values
('Cables & Wires','cables-wires','Reliable conductors for residential and commercial work.',1,true), ('Switches','switches','Everyday and premium switching solutions.',2,true), ('Sockets','sockets','Safe, durable power access.',3,true), ('Plugs','plugs','Plugs and adaptors for every installation.',4,true), ('Circuit Protection','circuit-protection','MCBs, RCCBs and protection devices.',5,true), ('Distribution Boards','distribution-boards','Organize and protect your circuits.',6,true), ('Lighting','lighting','Purposeful lighting for every environment.',7,true), ('LED Bulbs','led-bulbs','Efficient everyday illumination.',8,true), ('Downlights','downlights','Clean recessed lighting.',9,true), ('Floodlights','floodlights','High-output outdoor lighting.',10,true), ('Outdoor Lighting','outdoor-lighting','Light built for the elements.',11,true), ('Electrical Accessories','electrical-accessories','The finishing details of a good installation.',12,true), ('Conduits','conduits','Protect and route electrical cable.',13,true), ('Cable Management','cable-management','Keep every run clean and serviceable.',14,true), ('Earthing','earthing','Grounding and safety essentials.',15,true), ('Tools','tools','Professional tools for electrical work.',16,true), ('Solar & Power','solar-power','Practical independent power solutions.',17,true), ('Smart Home','smart-home','Connected control for modern spaces.',18,true), ('Security & CCTV','security-cctv','Visibility and peace of mind.',19,true), ('Industrial Electrical','industrial-electrical','Components for demanding environments.',20,true), ('Construction Electrical','construction-electrical','Site-ready electrical essentials.',21,true)
